// isSpecificResource is an inherited METHOD (checking the JSON "type"), even when
// the body's own JSON shape is "SpecificResource" wrapping a Model/Light/Camera.
// Annotation TARGETS shaped as SpecificResource, on the other hand, are parsed as
// actual SpecificResource instances, which shadow it with a boolean `true` OWN
// property instead. Reading `.isSpecificResource` without calling it would  be
// truthy in both cases regardless of the real answer, so this checks both shapes.
function resolvesToSpecificResource(value) {
  if (typeof value?.isSpecificResource === "function") return value.isSpecificResource();
  return value?.isSpecificResource === true;
}

async function loadIIIFManifest(manifestUrlOrJson) {
  let iiifManifest = new IIIFManifest(manifestUrlOrJson);
  await iiifManifest.loadManifest();
  let modelTarget;
  const modelTargets = [];
  let filteredAnnos;
  iiifManifest.modelUrls = new Array();

  if (iiifManifest.scenes.length > 0) {
    for (const [i, scene] of iiifManifest.scenes.entries()) { //TODO: support multiple scenes const manifestScene = scene;
    //if (!scene) return;
      // Root scene
      const manifestScene = iiifManifest.scenes[i];

      // Add scene BG color (getBackgroundColor() returns a Color instance;
      // downstream code expects a plain CSS hex string, same as the AIM3D loader)
      const backgroundColor = await manifestScene.getBackgroundColor();
      iiifManifest.scenes[i].background = backgroundColor?.CSS ?? null;

      // Load individual model annotations
      const annos = iiifManifest.annotationsFromScene(manifestScene);

      // Models only: cameras and lights are painted into the scene too
      // (applied separately, IIIF/presentation4.js), possibly wrapped in a
      // SpecificResource as well.
      filteredAnnos = annos.filter((anno) => {
        const body = anno.getBody()[0];
        const rawBody = anno.__jsonld?.body;
        return (
          anno.getMotivation()?.[0] === "painting" &&
          (rawBody ? isModelBody(rawBody) : (resolvesToSpecificResource(body) || body?.getType() === "model"))
        );
      });

      filteredAnnos.forEach((modelAnnotation) => {
        let modelUrl;
        if (resolvesToSpecificResource(modelAnnotation.getBody()[0])) {
          modelUrl = modelAnnotation.getBody()[0].getSource()?.id;
        } else {
          modelUrl = modelAnnotation.getBody()[0].id;
        }
        modelTarget = modelAnnotation.getTarget();
        if (modelUrl && modelTarget) {
          iiifManifest.modelUrls.push(modelUrl);
          modelTargets.push(modelTarget);
        }
      });
    }
  }
  return {
    manifest: iiifManifest.manifest,
    scenes: iiifManifest.scenes,
    annotations: filteredAnnos,
    modelUrls: iiifManifest.modelUrls,
    modelTarget: modelTarget,
    // One target per entry in modelUrls/annotations - a manifest can place
    // several models in the same scene, each with its own position selector.
    modelTargets,
  };
}

async function getAnnotations(iiifManifest, objectsConfig) {
  let ind = objectsConfig.index || 0;
  const modelAnnotations = iiifManifest.annotations[ind];
  if (!modelAnnotations) return;

  const target = iiifManifest.annotations?.[ind];

  if (target == null) {
    // handle missing (out-of-range or undefined)
    throw new Error(`No annotation at index ${ind}`);
  }

  // make sure we have an array to map over
  const items = Array.isArray(target) ? target : [target];

  await Promise.all(
    items.map(async (modelAnnotation) => {       
        if (resolvesToSpecificResource(modelAnnotation.getBody()[0])) {
          let transforms = new Array();

          try {
            const body = modelAnnotation.getBody?.();
            const first = Array.isArray(body) ? body[0] : null;
            transforms = first?.getTransform?.() || [];
          } catch (e) {
            // No transforms present so keep defaults
            //objectsConfig.models[ind].scale = {x: 1, y: 1, z: 1};
            //objectsConfig.models[ind].rotation = {x: 0, y: 0, z: 0};
            //objectsConfig.models[ind].position = {x: 0, y: 0, z: 0};
            //console.log("No transform present in specific resource body");
          }
          // Correct use of async-safe loop
          for (const transform of transforms) {
            if (!transform.isTransform) continue;

            const transformHandlers = [
              {
                key: "isScaleTransform",
                action: () => {
                  const scale = transform.getScale();
                  if (scale) {
                    objectsConfig.models[ind].scale = scale;
                  }
                  else {
                    objectsConfig.models[ind].scale = {x: 1, y: 1, z: 1};
                    console.log("No scale defined in scale transform");
                  }
                },
              },
              {
                key: "isRotateTransform",
                action: () => {
                  const rotation = transform.getRotation();
                  if (rotation) {
                    objectsConfig.models[ind].rotation = rotation;
                  }
                  else { 
                    objectsConfig.models[ind].rotation = {x: 0, y: 0, z: 0};
                    console.log("No rotation defined in rotate transform");
                  }
                },
              },
              {
                key: "isTranslateTransform",
                action: () => {
                  const translation = transform.getTranslation();
                  if (translation) {
                    objectsConfig.models[ind].position = translation;
                  }
                  else { 
                    objectsConfig.models[ind].position = {x: 0, y: 0, z: 0};
                  }
                },
              },
            ];

            for (const { key, action } of transformHandlers) {
              if (transform[key]) {
                action();
              }
            }
          }
        }

        // Position model within target scene if position selector present.
        // Each model annotation carries its own target, so index into
        // modelTargets rather than reusing whichever one loaded last.
        const currentTarget = iiifManifest.modelTargets?.[ind] ?? iiifManifest.modelTarget;
        if (resolvesToSpecificResource(currentTarget)) {
          const selector = currentTarget.getSelector();
          if (selector && selector.isPointSelector) {
            const position = selector.getLocation();
            if (position) {
              objectsConfig.models[ind].position.x += position.x;
              objectsConfig.models[ind].position.y += position.y;
              objectsConfig.models[ind].position.z += position.z;
            }
          }
        }
        }));
  
  return iiifManifest.annotations;
}

class AIM3DManifest {
  constructor(manifest) {
    if (typeof manifest === "string" && manifest.trim().startsWith("{")) {
      this.manifestJson = JSON.parse(manifest);
      this.manifestUrl = null;
    } else if (typeof manifest === "object") {
      this.manifestJson = manifest;
      this.manifestUrl = null;
    } else {
      this.manifestUrl = manifest;
      this.manifestJson = null;
    }
  }

  async loadManifest() {
    if (this.manifestUrl) {
      const response = await fetch(this.manifestUrl);
      this.manifestJson = await response.json();
    }

    this.manifest = this.manifestJson;

    this.scenes = this.manifest?.items?.filter(
      item => item.type === "Scene"
    ) || [];
  }

  annotationsFromScene(scene) {
    const result = [];

    for (const page of scene?.items || []) {
      if (page.type !== "AnnotationPage") continue;

      for (const annotation of page.items || []) {
        result.push(annotation);
      }
    }

    return result;
  }
}

async function loadAIM3IFManifest(manifestUrlOrJson) {
  const aim3dManifest = new AIM3DManifest(manifestUrlOrJson);

  await aim3dManifest.loadManifest();

  normalizeAIM3DManifest(aim3dManifest.manifest);

  const validation = validateAIM3DManifest(aim3dManifest.manifest);
  if (!validation.valid) {
    const detail = formatAIM3DManifestValidationErrors(validation.errors);
    throw new Error(`Invalid AIM3D manifest.\n${detail}`);
  }

  const modelUrls = [];
  let modelTarget = null;
  let filteredAnnos = [];

  for (const scene of aim3dManifest.scenes) {
    // Leave background unset (rather than defaulting to black) when the
    // manifest doesn't specify one, so the viewer's own default background
    // applies - matching how the IIIF loader handles a missing color.
    scene.background = scene.backgroundColor || null;

    const annos = aim3dManifest.annotationsFromScene(scene);

    // A Model body, or (Presentation 4 export with transforms) a
    // SpecificResource around one - never the scene's cameras or lights.
    filteredAnnos = annos.filter(
      anno =>
        anno.motivation?.includes("painting") &&
        isModelBody(anno.body)
    );

    for (const anno of filteredAnnos) {
      const modelUrl = modelUrlOf(anno.body);

      if (modelUrl) {
        modelUrls.push(modelUrl);
      }

      modelTarget = anno.target;
    }
  }

  aim3dManifest.modelUrls = modelUrls;
  aim3dManifest.modelTarget = modelTarget;

  return {
    manifest: aim3dManifest.manifest,
    scenes: aim3dManifest.scenes,
    annotations: filteredAnnos,
    modelUrls,
    modelTarget
  };
}


function applyManifestConfig(manifest, objectsConfig) {
  const transform =
    manifest.AIM3DViewer?.modelTransform;

  if (!transform) return;

  const model = objectsConfig.models[0];

  model.position = {
    x: transform.position?.[0] ?? 0,
    y: transform.position?.[1] ?? 0,
    z: transform.position?.[2] ?? 0
  };

  model.rotation = {
    x: transform.rotation?.x ?? 0,
    y: transform.rotation?.y ?? 0,
    z: transform.rotation?.z ?? 0
  };

  model.scale = {
    x: transform.scale?.[0] ?? 1,
    y: transform.scale?.[1] ?? 1,
    z: transform.scale?.[2] ?? 1
  };

  model.wireframe =
    transform.wireframe ?? false;

  model.shadingMode =
    transform.shadingMode ?? "standard";

  model.customShader =
    transform.customShader ?? null;
}

function getManifestWindowState(manifest) {
  const windowState = manifest?.AIM3DViewer?.viewer?.window;
  if (!windowState) return null;

  const position = Array.isArray(windowState.position)
    ? { x: windowState.position[0], y: windowState.position[1] }
    : windowState.position;

  return {
    position,
    size: windowState.size,
  };
}

function isPlainObject(value) {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

function nonEmptyString(value) {
  return typeof value === "string" && value.trim() !== "" ? value : undefined;
}

// Position/size are stored as {x, y} / {width, height} in viewer-settings.json.
function toXY(value) {
  if (Array.isArray(value)) return { x: value[0], y: value[1] };
  return isPlainObject(value) ? { x: value.x, y: value.y } : undefined;
}

function toPanelState(panel) {
  if (!isPlainObject(panel)) return undefined;
  const state = {};
  const position = toXY(panel.position);
  if (position) state.position = position;
  if (isPlainObject(panel.size)) state.size = { ...panel.size };
  return state;
}

// Merges the deployment settings carried by an AIM3D manifest into `config`
// (the object loaded from viewer-settings.json). viewer-settings.json stays the
// fallback: only values the manifest actually defines are overwritten, so
// manifests written before these fields existed leave the config untouched.
//
// Bootstrap keys that are needed *before* a manifest can be fetched (the
// manifest URL/source in entity.metadata, viewer.lightweight, viewer.editor)
// intentionally remain viewer-settings.json only.
//
// Settings with runtime side effects (theme, toolbars, performance mode, ...)
// are applied separately by Viewer.import3IFManifest().
function applyManifestSettings(manifest, config) {
  const block = manifest?.AIM3DViewer;
  if (!isPlainObject(block) || !isPlainObject(config)) return false;

  const viewer = isPlainObject(block.viewer) ? block.viewer : {};
  const integration = isPlainObject(block.integration) ? block.integration : {};
  let applied = false;
  const set = (target, key, value) => {
    if (value === undefined) return;
    target[key] = value;
    applied = true;
  };

  config.viewer ??= {};
  config.entity ??= {};

  set(config, "mainUrl", nonEmptyString(viewer.mainUrl));
  set(config, "baseModulePath", nonEmptyString(viewer.baseModulePath));
  set(config.viewer, "background", nonEmptyString(viewer.background));
  if (isPlainObject(viewer.credits)) set(config.viewer, "credits", structuredClone(viewer.credits));
  if (isPlainObject(viewer.auth)) set(config.viewer, "auth", { ...viewer.auth });
  set(config.viewer, "manifestoForm", toPanelState(viewer.manifestoForm));
  set(config.viewer, "metadataContainer", toPanelState(viewer.metadataContainer));

  set(config.entity, "exportViewerUrl", nonEmptyString(integration.exportViewerUrl));
  if (isPlainObject(integration.api)) {
    config.api ??= {};
    set(config.api, "thumbnailUploadEndpoint", nonEmptyString(integration.api.thumbnailUploadEndpoint));
  }

  return applied;
}

// Settings that decide how the UI is *built* (viewer.lightweight, viewer.editor,
// viewer.sandbox, viewer.presentationMode) must be known before any UI exists,
// i.e. before the regular manifest load. Viewer.MainInit() therefore peeks at
// the configured AIM3D manifest and calls this. Only strict booleans are
// accepted; anything else leaves the viewer-settings.json value in place.
function applyManifestBootstrapSettings(manifest, config) {
  const viewer = manifest?.AIM3DViewer?.viewer;
  if (!isPlainObject(viewer) || !isPlainObject(config)) return false;

  let applied = false;
  config.viewer ??= {};
  // manifest key -> viewer-settings.json key
  const keys = {
    lightweight: "lightweight",
    editor: "editor",
    sandbox: "sandboxMode",
    presentationMode: "presentationMode",
  };
  for (const [manifestKey, configKey] of Object.entries(keys)) {
    if (typeof viewer[manifestKey] === "boolean") {
      config.viewer[configKey] = viewer[manifestKey];
      applied = true;
    }
  }
  return applied;
}

